fn make_move(board: &mut [[i32; 4]; 4], player: i32) {
    println!("Player {}'s turn", player);
    let mut column = 0;
    loop {
        println!("Enter column (0-3): ");
        let mut input = String::new();
        io::stdin().read_line(&mut input).expect("Failed to read line");
        column = input.trim().parse().expect("Please type a number!");
        if column < 0 || column > 3 {
            println!("Column out of range!");
        } else if board[0][column] != 0 {
            println!("Column full!");
        } else {
            for row in (0..4).rev() {
                if board[row][column] == 0 {
                    board[row][column] = player;
                    break;
                }
            }
            break;
        }
    }
}
